-- 202609300001_crm_schema.sql
begin;
create schema if not exists app_private;

create table public.agents (
  id text primary key, name text not null, email text not null unique, phone text not null,
  avatar text, specialization text not null, locations text[] not null default '{}',
  languages text[] not null default '{}', status text not null default 'ACTIVE' check (status in ('ACTIVE','INACTIVE'))
);
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade, name text not null,
  role text not null check (role in ('ADMIN','AGENT')), agent_id text unique references public.agents(id),
  created_at timestamptz not null default now(), check (role <> 'AGENT' or agent_id is not null)
);
create table public.properties (
  id bigint generated by default as identity primary key, slug text not null unique, title text not null,
  category text not null, purpose text not null check (purpose in ('buy','rent','off-plan','commercial')),
  location text not null, location_slug text not null, city text not null default 'Dubai',
  price numeric(16,2) not null check (price > 0), currency text not null default 'AED',
  bedrooms integer not null default 0 check (bedrooms >= 0), bathrooms integer not null default 0 check (bathrooms >= 0),
  area numeric not null check (area > 0), area_unit text not null default 'sq ft', featured boolean not null default false,
  off_plan boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  tenure text default 'Freehold', furnished text default 'Unfurnished', reference text, images text[] not null,
  coordinates jsonb not null default '{"lat":25.2048,"lng":55.2708}', description text not null,
  amenities text[] not null default '{}', agent jsonb not null default '{}',
  status text not null default 'DRAFT' check (status in ('ACTIVE','DRAFT','SOLD','RENTED','INACTIVE')),
  check (cardinality(images) > 0)
);
create table public.leads (
  id text primary key default ('LEAD-' || gen_random_uuid()::text),
  customer_name text not null, customer_email text not null, customer_phone text not null, customer_country text not null,
  property_id bigint references public.properties(id), source text not null, purpose text not null default 'buy',
  budget_min numeric(16,2) not null default 0 check (budget_min >= 0), budget_max numeric(16,2) not null default 0 check (budget_max >= 0),
  preferred_location text not null default '', preferred_contact text not null default 'Call',
  status text not null default 'NEW' check (status in ('NEW','ASSIGNED','CONTACTED','QUALIFIED','FOLLOW_UP','VIEWING_SCHEDULED','VIEWING_COMPLETED','NEGOTIATION','WON','LOST')),
  priority text not null default 'MEDIUM' check (priority in ('LOW','MEDIUM','HIGH','URGENT')),
  assigned_agent_id text references public.agents(id), assigned_at timestamptz, next_follow_up timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  final_property_id bigint references public.properties(id), deal_value numeric(16,2) check (deal_value > 0), closing_date timestamptz, deal_notes text,
  lost_reason text, lost_notes text,
  check (status <> 'WON' or (deal_value is not null and final_property_id is not null and closing_date is not null)),
  check (status <> 'LOST' or nullif(lost_reason,'') is not null)
);
create table public.lead_activities (
  id text primary key default ('ACT-' || gen_random_uuid()::text), lead_id text not null references public.leads(id),
  type text not null, message text not null, author text not null, author_profile_id uuid references public.profiles(id),
  created_at timestamptz not null default now()
);
create table public.lead_notes (
  id text primary key default ('NOTE-' || gen_random_uuid()::text), lead_id text not null references public.leads(id),
  content text not null check (length(content) between 1 and 10000), author text not null,
  author_profile_id uuid references public.profiles(id), created_at timestamptz not null default now()
);
create table public.tasks (
  id text primary key default ('TASK-' || gen_random_uuid()::text), lead_id text not null references public.leads(id),
  agent_id text not null references public.agents(id), title text not null, type text not null default 'Call',
  due_date timestamptz not null, priority text not null default 'MEDIUM' check (priority in ('LOW','MEDIUM','HIGH','URGENT')),
  status text not null default 'PENDING' check (status in ('PENDING','IN_PROGRESS','COMPLETED','CANCELLED')),
  notes text not null default '', is_follow_up boolean not null default false
);
create table public.viewings (
  id text primary key default ('VIEW-' || gen_random_uuid()::text), lead_id text not null references public.leads(id),
  property_id bigint not null references public.properties(id), agent_id text not null references public.agents(id),
  date timestamptz not null, meeting_location text not null, notes text not null default '',
  status text not null default 'SCHEDULED' check (status in ('SCHEDULED','COMPLETED','CANCELLED')),
  outcome text, outcome_notes text, completed_at timestamptz
);
create table public.notifications (
  id text primary key default ('NOTICE-' || gen_random_uuid()::text), lead_id text not null references public.leads(id),
  agent_id text references public.agents(id), message text not null, created_at timestamptz not null default now(), read_by text[] not null default '{}'
);
create table public.crm_settings (
  id integer primary key default 1 check (id = 1), company text not null, email text not null,
  phone text not null, default_view text not null default 'table' check (default_view in ('table','kanban'))
);
create table public.public_content (kind text primary key, data jsonb not null, updated_at timestamptz not null default now());
create table public.newsletter_subscriptions (email text primary key, created_at timestamptz not null default now());
create table public.visitor_preferences (token_hash text primary key, favorites bigint[] not null default '{}', updated_at timestamptz not null default now());

create index leads_agent_status on public.leads(assigned_agent_id,status);
create index leads_created_at on public.leads(created_at desc);
create index tasks_agent_due on public.tasks(agent_id,due_date);
create index tasks_lead on public.tasks(lead_id);
create index viewings_agent_date on public.viewings(agent_id,date);
create index activities_lead_created on public.lead_activities(lead_id,created_at desc);
create index notes_lead on public.lead_notes(lead_id);
create index notifications_agent_created on public.notifications(agent_id,created_at desc);
create index properties_status on public.properties(status);

create function app_private.is_admin() returns boolean language sql stable security definer set search_path = '' as $$
  select exists(select 1 from public.profiles where id = auth.uid() and role = 'ADMIN');
$$;
create function app_private.agent_id() returns text language sql stable security definer set search_path = '' as $$
  select p.agent_id from public.profiles p where id = auth.uid();
$$;
create function app_private.has_profile() returns boolean language sql stable security definer set search_path = '' as $$
  select exists(select 1 from public.profiles where id = auth.uid());
$$;
create function app_private.can_read_lead(lead_key text) returns boolean language sql stable security definer set search_path = '' as $$
  select app_private.is_admin() or exists(select 1 from public.leads where id = lead_key and assigned_agent_id = app_private.agent_id());
$$;

alter table public.profiles enable row level security;
alter table public.agents enable row level security;
alter table public.properties enable row level security;
alter table public.leads enable row level security;
alter table public.lead_activities enable row level security;
alter table public.lead_notes enable row level security;
alter table public.tasks enable row level security;
alter table public.viewings enable row level security;
alter table public.notifications enable row level security;
alter table public.crm_settings enable row level security;
alter table public.public_content enable row level security;
alter table public.newsletter_subscriptions enable row level security;
alter table public.visitor_preferences enable row level security;

create policy profiles_read on public.profiles for select to authenticated using (id = (select auth.uid()) or (select app_private.is_admin()));
create policy agents_read on public.agents for select to authenticated using ((select app_private.is_admin()) or id = (select app_private.agent_id()));
create policy properties_read on public.properties for select to anon,authenticated using (status = 'ACTIVE' or (select app_private.has_profile()));
create policy leads_read on public.leads for select to authenticated using ((select app_private.is_admin()) or assigned_agent_id = (select app_private.agent_id()));
create policy activities_read on public.lead_activities for select to authenticated using (app_private.can_read_lead(lead_id));
create policy notes_read on public.lead_notes for select to authenticated using (app_private.can_read_lead(lead_id));
create policy tasks_read on public.tasks for select to authenticated using (app_private.can_read_lead(lead_id) and ((select app_private.is_admin()) or agent_id = (select app_private.agent_id())));
create policy viewings_read on public.viewings for select to authenticated using (app_private.can_read_lead(lead_id) and ((select app_private.is_admin()) or agent_id = (select app_private.agent_id())));
create policy notifications_read on public.notifications for select to authenticated using ((select app_private.is_admin()) or (agent_id = (select app_private.agent_id()) and app_private.can_read_lead(lead_id)));
create policy settings_read on public.crm_settings for select to authenticated using ((select app_private.has_profile()));
create policy content_read on public.public_content for select to anon,authenticated using (true);

revoke all on public.profiles,public.agents,public.properties,public.leads,public.lead_activities,public.lead_notes,public.tasks,public.viewings,public.notifications,public.crm_settings,public.public_content,public.newsletter_subscriptions,public.visitor_preferences from anon,authenticated;
grant all on public.profiles,public.agents,public.properties,public.leads,public.lead_activities,public.lead_notes,public.tasks,public.viewings,public.notifications,public.crm_settings,public.public_content,public.newsletter_subscriptions,public.visitor_preferences to service_role;
grant usage, select on sequence public.properties_id_seq to service_role;
grant select on public.properties,public.public_content to anon,authenticated;
grant select on public.profiles,public.agents,public.leads,public.lead_activities,public.lead_notes,public.tasks,public.viewings,public.notifications,public.crm_settings to authenticated;
revoke all on all functions in schema app_private from public,anon,authenticated;
grant usage on schema app_private to anon,authenticated;
grant execute on function app_private.is_admin(),app_private.agent_id(),app_private.has_profile(),app_private.can_read_lead(text) to anon,authenticated;
commit;


-- 202609300002_crm_workflows.sql
begin;
create function app_private.require_text(value text, title text) returns text language plpgsql immutable set search_path = '' as $$
begin
  if nullif(btrim(value),'') is null then raise exception '% is required.', title; end if;
  if length(value) > 10000 then raise exception '% is too long.', title; end if;
  return btrim(value);
end $$;
create function app_private.event(lead_key text, event_type text, message_text text, actor_name text default null) returns void language plpgsql security definer set search_path = '' as $$
begin
  insert into public.lead_activities(lead_id,type,message,author,author_profile_id)
  values(lead_key,event_type,message_text,coalesce(actor_name,(select name from public.profiles where id=auth.uid()),'Website visitor'),(select id from public.profiles where id=auth.uid()));
  update public.leads set updated_at=now() where id=lead_key;
end $$;
create function app_private.notify(lead_key text, message_text text) returns void language sql security definer set search_path = '' as $$
  insert into public.notifications(lead_id,agent_id,message) select id,assigned_agent_id,message_text from public.leads where id=lead_key;
$$;
create function app_private.stage(lead_key text, next_status text) returns void language plpgsql security definer set search_path = '' as $$
begin
  if exists(select 1 from public.leads where id=lead_key and status<>next_status) then
    update public.leads set status=next_status,updated_at=now() where id=lead_key;
    perform app_private.event(lead_key,'STATUS_CHANGED','Lead moved to ' || replace(initcap(lower(next_status)),'_',' ') || '.');
  end if;
end $$;
create function app_private.sync_follow_up(lead_key text) returns void language sql security definer set search_path = '' as $$
  update public.leads set next_follow_up=(select min(due_date) from public.tasks where lead_id=lead_key and is_follow_up and status not in ('COMPLETED','CANCELLED')) where id=lead_key;
$$;
create function app_private.close_work(lead_key text) returns void language plpgsql security definer set search_path = '' as $$
begin
  update public.tasks set status='CANCELLED' where lead_id=lead_key and status not in ('COMPLETED','CANCELLED');
  update public.viewings set status='CANCELLED' where lead_id=lead_key and status='SCHEDULED';
  perform app_private.sync_follow_up(lead_key);
end $$;
create function app_private.create_lead(payload jsonb, website boolean) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  result public.leads; prop public.properties; source_text text; budget_lo numeric := 0; budget_hi numeric := 0;
  name_text text := app_private.require_text(payload->>'name','Customer name');
  email_text text := lower(app_private.require_text(payload->>'email','Email'));
  phone_text text := app_private.require_text(payload->>'phone','Phone');
begin
  if length(name_text)<2 or email_text !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or phone_text !~ '^[+0-9 ()-]{7,20}$' then raise exception 'Enter a valid name, email and phone number.'; end if;
  if nullif(payload->>'propertyId','') is not null then
    select * into prop from public.properties where id=(payload->>'propertyId')::bigint;
    if prop.id is null or (website and prop.status<>'ACTIVE') then raise exception 'Property is unavailable.'; end if;
  end if;
  if website then
    if length(app_private.require_text(payload->>'message','Message'))<10 then raise exception 'Your message must contain at least 10 characters.'; end if;
    perform pg_advisory_xact_lock(hashtext(email_text));
    if (select count(*) from public.leads where customer_email=email_text and created_at>now()-interval '1 day')>=10 then raise exception 'Too many inquiries for this email. Please try again tomorrow.'; end if;
    source_text:=case when prop.id is null then 'Contact Form' else 'Property Detail' end;
  else source_text:=coalesce(nullif(payload->>'source',''),'Other'); end if;
  case payload->>'budget'
    when 'Under 1 million' then budget_hi:=1000000;
    when '1–5 million' then budget_lo:=1000000; budget_hi:=5000000;
    when '5–15 million' then budget_lo:=5000000; budget_hi:=15000000;
    when '15 million and above' then budget_lo:=15000000;
    else budget_hi:=coalesce(nullif(payload->>'budgetMax','')::numeric,0);
  end case;
  insert into public.leads(customer_name,customer_email,customer_phone,customer_country,property_id,source,purpose,budget_min,budget_max,preferred_location,preferred_contact,priority)
  values(name_text,email_text,phone_text,app_private.require_text(payload->>'country','Country'),prop.id,source_text,
    coalesce(payload->>'purpose',payload->>'interest',prop.purpose,'buy'),budget_lo,budget_hi,coalesce(prop.location,payload->>'location',''),coalesce(payload->>'preferredContact','Call'),case when website then 'MEDIUM' else coalesce(payload->>'priority','MEDIUM') end)
  returning * into result;
  perform app_private.event(result.id,'LEAD_CREATED','Lead created from '||source_text||'.');
  if nullif(btrim(payload->>'message'),'') is not null then insert into public.lead_notes(lead_id,content,author) values(result.id,payload->>'message',name_text); end if;
  perform app_private.notify(result.id,'New inquiry from '||name_text||'.');
  return jsonb_build_object('id',result.id,'createdAt',result.created_at);
end $$;
create function public.submit_inquiry(payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  if octet_length(payload::text)>24000 then raise exception 'Inquiry is too large.'; end if;
  return app_private.create_lead(payload,true);
end $$;

create function public.crm_command(command text, payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  actor public.profiles; lead public.leads; agent public.agents; task public.tasks; viewing public.viewings;
  prop public.properties; result jsonb; lead_key text; next_stage text; event_date timestamptz; strings text[]; imgs text[];
  row_key text := coalesce(payload->>'id',payload->>'leadId'); priority_value text; reason text;
begin
  select * into actor from public.profiles where id=auth.uid();
  if actor.id is null then raise exception 'Sign in with an authorized CRM account.' using errcode='42501'; end if;
  if octet_length(payload::text)>100000 then raise exception 'Request is too large.'; end if;
  if command in ('createLead','assign','saveProperty','saveSettings') and actor.role<>'ADMIN' then raise exception 'Administrator access is required.' using errcode='42501'; end if;
  if command='createLead' then return app_private.create_lead(payload,false); end if;
  if command='saveSettings' then
    insert into public.crm_settings(id,company,email,phone,default_view) values(1,app_private.require_text(payload->>'company','Company'),app_private.require_text(payload->>'email','Email'),app_private.require_text(payload->>'phone','Phone'),coalesce(payload->>'defaultView','table'))
    on conflict(id) do update set company=excluded.company,email=excluded.email,phone=excluded.phone,default_view=excluded.default_view;
    return jsonb_build_object('id',1);
  end if;
  if command='saveAgent' then
    select * into agent from public.agents where id=row_key for update;
    if agent.id is null or (actor.role<>'ADMIN' and actor.agent_id<>agent.id) then raise exception 'Agent access denied.' using errcode='42501'; end if;
    update public.agents set name=app_private.require_text(payload->>'name','Name'),phone=app_private.require_text(payload->>'phone','Phone'),specialization=app_private.require_text(payload->>'specialization','Specialization'),languages=regexp_split_to_array(app_private.require_text(payload->>'languages','Languages'),'\s*,\s*'),status=case when actor.role='ADMIN' then coalesce(payload->>'status',agent.status) else agent.status end where id=agent.id;
    update public.profiles set name=payload->>'name' where agent_id=agent.id;
    return jsonb_build_object('id',agent.id);
  end if;
  if command='saveProperty' then
    if nullif(payload->>'id','') is not null then select * into prop from public.properties where id=(payload->>'id')::bigint for update; if prop.id is null then raise exception 'Property not found.'; end if; end if;
    if jsonb_typeof(payload->'images')='array' then select array_agg(value) into imgs from jsonb_array_elements_text(payload->'images'); else imgs:=regexp_split_to_array(btrim(payload->>'images'),E'\n+'); end if;
    if coalesce(cardinality(imgs),0)=0 or exists(select 1 from unnest(imgs) i where i !~ '^https?://[^[:space:]]+$') then raise exception 'Provide valid http or https image URLs.'; end if;
    if jsonb_typeof(payload->'amenities')='array' then select array_agg(value) into strings from jsonb_array_elements_text(payload->'amenities'); else strings:=regexp_split_to_array(coalesce(payload->>'amenities',''),'\s*,\s*'); end if;
    if prop.id is null then
      prop.id:=nextval(pg_get_serial_sequence('public.properties','id'));
      prop.slug:=trim(both '-' from regexp_replace(lower(app_private.require_text(payload->>'title','Title')),'[^a-z0-9]+','-','g'))||'-'||prop.id;
    end if;
    insert into public.properties(id,slug,title,category,purpose,location,location_slug,price,bedrooms,bathrooms,area,description,images,amenities,featured,status,off_plan,reference,agent)
    values(prop.id,prop.slug,app_private.require_text(payload->>'title','Title'),app_private.require_text(payload->>'category','Category'),payload->>'purpose',app_private.require_text(payload->>'location','Location'),app_private.require_text(payload->>'locationSlug','Location reference'),(payload->>'price')::numeric,(payload->>'bedrooms')::integer,(payload->>'bathrooms')::integer,(payload->>'area')::numeric,app_private.require_text(payload->>'description','Description'),imgs,coalesce(strings,'{}'),coalesce((payload->>'featured')::boolean,false),payload->>'status',(payload->>'purpose')='off-plan',coalesce(prop.reference,'DH-'||prop.id),coalesce(prop.agent,(select jsonb_build_object('name',name,'role','Property Advisor','languages',array_to_string(languages,' · '),'image',avatar) from public.agents order by id limit 1),'{}'))
    on conflict(id) do update set title=excluded.title,category=excluded.category,purpose=excluded.purpose,location=excluded.location,location_slug=excluded.location_slug,price=excluded.price,bedrooms=excluded.bedrooms,bathrooms=excluded.bathrooms,area=excluded.area,description=excluded.description,images=excluded.images,amenities=excluded.amenities,featured=excluded.featured,status=excluded.status,off_plan=excluded.off_plan,updated_at=now();
    return jsonb_build_object('id',prop.id);
  end if;
  if command='readNotifications' then
    insert into public.notifications(id,lead_id,agent_id,message,created_at)
      select 'due-'||t.id||'-'||to_char(t.due_date at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),t.lead_id,t.agent_id,case when t.due_date<now() then 'Overdue: ' else 'Due today: ' end||t.title,t.due_date
      from public.tasks t where app_private.can_read_lead(t.lead_id) and (actor.role='ADMIN' or t.agent_id=actor.agent_id) and t.status not in ('COMPLETED','CANCELLED') and t.due_date<now()+interval '1 day'
      on conflict(id) do update set agent_id=excluded.agent_id;
    update public.notifications n set read_by=array_append(n.read_by,actor.id::text) where (actor.role='ADMIN' or (n.agent_id=actor.agent_id and app_private.can_read_lead(n.lead_id))) and not (actor.id::text=any(n.read_by)) and (payload->>'id' is null or n.id=payload->>'id');
    return '{}';
  end if;
  if command='updateTask' then
    select * into task from public.tasks where id=row_key;
    if task.id is null then raise exception 'Task not found.'; end if;
    lead_key:=task.lead_id;
  elsif command='updateViewing' then
    select * into viewing from public.viewings where id=row_key;
    if viewing.id is null then raise exception 'Viewing not found.'; end if;
    lead_key:=viewing.lead_id;
  else lead_key:=coalesce(payload->>'leadId',payload->>'id'); end if;
  select * into lead from public.leads where id=lead_key for update;
  if lead.id is null or not app_private.can_read_lead(lead.id) then raise exception 'This lead is unavailable or not assigned to you.' using errcode='42501'; end if;
  if command in ('assign','createTask','createViewing','won','lost') and lead.status in ('WON','LOST') then raise exception 'This lead is closed. Reopen it before scheduling work.'; end if;
  case command
  when 'assign' then
    select * into agent from public.agents where id=payload->>'agentId' and status='ACTIVE';
    if agent.id is null then raise exception 'Select an active agent.'; end if;
    update public.leads set assigned_agent_id=agent.id,assigned_at=now() where id=lead.id;
    update public.tasks set agent_id=agent.id where lead_id=lead.id and status not in ('COMPLETED','CANCELLED');
    update public.viewings set agent_id=agent.id where lead_id=lead.id and status='SCHEDULED';
    if lead.status='NEW' then perform app_private.stage(lead.id,'ASSIGNED'); end if;
    perform app_private.event(lead.id,'AGENT_ASSIGNED',case when lead.assigned_agent_id is null then 'Assigned to ' else 'Reassigned to ' end||agent.name||'.');
    perform app_private.notify(lead.id,lead.customer_name||' assigned to '||agent.name||'.');
  when 'status' then
    next_stage:=payload->>'status';
    if next_stage not in ('NEW','ASSIGNED','CONTACTED','QUALIFIED','FOLLOW_UP','NEGOTIATION') then raise exception 'Use the dedicated viewing or outcome action for this stage.'; end if;
    if lead.status in ('WON','LOST') and next_stage<>'FOLLOW_UP' then raise exception 'Reopen closed leads in Follow Up.'; end if;
    if next_stage<>'NEW' and lead.assigned_agent_id is null then raise exception 'Assign an agent first.'; end if;
    if next_stage='NEW' and lead.assigned_agent_id is not null then raise exception 'Assigned leads cannot return to New.'; end if;
    if lead.status in ('WON','LOST') then update public.leads set status='FOLLOW_UP',final_property_id=null,deal_value=null,closing_date=null,deal_notes=null,lost_reason=null,lost_notes=null where id=lead.id; perform app_private.event(lead.id,'STATUS_CHANGED','Closed lead reopened in Follow Up.');
    else perform app_private.stage(lead.id,next_stage); end if;
  when 'priority' then
    update public.leads set priority=payload->>'priority' where id=lead.id;
    perform app_private.event(lead.id,'PRIORITY_CHANGED','Priority changed to '||(payload->>'priority')||'.');
  when 'note' then
    insert into public.lead_notes(lead_id,content,author,author_profile_id) values(lead.id,app_private.require_text(payload->>'content','Note'),actor.name,actor.id);
    perform app_private.event(lead.id,'NOTE_ADDED','A note was added.');
  when 'communication' then
    if payload->>'type' not in ('Call','Email','WhatsApp') then raise exception 'Choose a communication type.'; end if;
    if lead.assigned_agent_id is null then raise exception 'Assign an agent first.'; end if;
    perform app_private.event(lead.id,upper(payload->>'type')||'_LOGGED',(payload->>'type')||' logged: '||app_private.require_text(payload->>'content','Conversation notes'));
    if lead.status in ('NEW','ASSIGNED') then perform app_private.stage(lead.id,'CONTACTED'); end if;
  when 'createTask' then
    if lead.assigned_agent_id is null then raise exception 'Assign an agent before scheduling work.'; end if;
    event_date:=(payload->>'dueDate')::timestamptz;
    if event_date is null or event_date<=now() then raise exception 'Choose a future date and time.'; end if;
    insert into public.tasks(lead_id,agent_id,title,type,due_date,priority,notes,is_follow_up) values(lead.id,lead.assigned_agent_id,app_private.require_text(payload->>'title','Title'),coalesce(payload->>'type','Call'),event_date,coalesce(payload->>'priority',lead.priority),coalesce(payload->>'notes',''),coalesce((payload->>'isFollowUp')::boolean,false)) returning * into task;
    perform app_private.sync_follow_up(lead.id);
    perform app_private.event(lead.id,case when task.is_follow_up then 'FOLLOW_UP_CREATED' else 'TASK_CREATED' end,task.title||' scheduled for '||event_date||'.');
    if task.is_follow_up and lead.status not in ('VIEWING_SCHEDULED','NEGOTIATION') then perform app_private.stage(lead.id,'FOLLOW_UP'); end if;
    perform app_private.notify(lead.id,'Task scheduled for '||lead.customer_name||'.');
    return jsonb_build_object('id',task.id);
  when 'updateTask' then
    select * into task from public.tasks where id=row_key for update;
    if actor.role<>'ADMIN' and task.agent_id<>actor.agent_id then raise exception 'Task access denied.'; end if;
    if task.status in ('COMPLETED','CANCELLED') then raise exception 'This task is already closed.'; end if;
    if payload ? 'dueDate' then event_date:=(payload->>'dueDate')::timestamptz; if event_date is null or event_date<=now() then raise exception 'Choose a future date and time.'; end if; end if;
    update public.tasks set status=coalesce(payload->>'status',status),due_date=coalesce(event_date,due_date) where id=task.id;
    perform app_private.sync_follow_up(lead.id);
    perform app_private.event(lead.id,'TASK_UPDATED',task.title||': '||case when event_date is not null then 'rescheduled to '||event_date else payload->>'status' end||'.');
    return jsonb_build_object('id',task.id);
  when 'createViewing' then
    if lead.assigned_agent_id is null then raise exception 'Assign an agent before scheduling a viewing.'; end if;
    event_date:=(payload->>'date')::timestamptz;
    if event_date is null or event_date<=now() then raise exception 'Choose a future date and time.'; end if;
    perform pg_advisory_xact_lock(hashtext(lead.assigned_agent_id));
    if exists(select 1 from public.viewings where agent_id=lead.assigned_agent_id and status='SCHEDULED' and abs(extract(epoch from date-event_date))<3600) then raise exception 'This agent has a viewing within one hour.'; end if;
    select * into prop from public.properties where id=coalesce(nullif(payload->>'propertyId','')::bigint,lead.property_id);
    if prop.id is null then raise exception 'Select a property.'; end if;
    insert into public.viewings(lead_id,property_id,agent_id,date,meeting_location,notes) values(lead.id,prop.id,lead.assigned_agent_id,event_date,app_private.require_text(payload->>'meetingLocation','Meeting location'),coalesce(payload->>'notes','')) returning * into viewing;
    perform app_private.stage(lead.id,'VIEWING_SCHEDULED');
    perform app_private.event(lead.id,'VIEWING_CREATED','Viewing at '||prop.title||' scheduled for '||event_date||'.');
    perform app_private.notify(lead.id,'Viewing scheduled for '||lead.customer_name||'.');
    return jsonb_build_object('id',viewing.id);
  when 'updateViewing' then
    select * into viewing from public.viewings where id=row_key for update;
    if actor.role<>'ADMIN' and viewing.agent_id<>actor.agent_id then raise exception 'Viewing access denied.'; end if;
    if viewing.status<>'SCHEDULED' then raise exception 'This viewing is already closed.'; end if;
    if payload->>'action'='reschedule' then
      event_date:=(payload->>'date')::timestamptz;
      if event_date is null or event_date<=now() then raise exception 'Choose a future date and time.'; end if;
      perform pg_advisory_xact_lock(hashtext(viewing.agent_id));
      if exists(select 1 from public.viewings where id<>viewing.id and agent_id=viewing.agent_id and status='SCHEDULED' and abs(extract(epoch from date-event_date))<3600) then raise exception 'This agent has another viewing within one hour.'; end if;
      update public.viewings set date=event_date where id=viewing.id;
      perform app_private.event(lead.id,'VIEWING_RESCHEDULED','Viewing rescheduled to '||event_date||'.');
    elsif payload->>'action'='cancel' then
      update public.viewings set status='CANCELLED' where id=viewing.id;
      perform app_private.event(lead.id,'VIEWING_CANCELLED','Viewing cancelled.');
      if lead.status='VIEWING_SCHEDULED' and not exists(select 1 from public.viewings where lead_id=lead.id and status='SCHEDULED') then perform app_private.stage(lead.id,'FOLLOW_UP'); end if;
    elsif payload->>'action'='complete' then
      if viewing.date>now() then raise exception 'A viewing can only be completed after its scheduled time.'; end if;
      if payload->>'outcome' is null or payload->>'outcome' not in ('Interested','Very Interested','Need Follow-Up','Not Interested','Second Viewing Required') then raise exception 'Choose a viewing outcome.'; end if;
      update public.viewings set status='COMPLETED',outcome=payload->>'outcome',outcome_notes=app_private.require_text(payload->>'notes','Outcome notes'),completed_at=now() where id=viewing.id;
      perform app_private.event(lead.id,'VIEWING_COMPLETED','Viewing completed: '||(payload->>'outcome')||'. '||(payload->>'notes'));
      perform app_private.stage(lead.id,'VIEWING_COMPLETED');
      perform app_private.stage(lead.id,case when payload->>'outcome' in ('Interested','Very Interested') then 'NEGOTIATION' else 'FOLLOW_UP' end);
    else raise exception 'Choose a viewing action.'; end if;
    return jsonb_build_object('id',viewing.id);
  when 'won' then
    if coalesce((payload->>'confirmed')::boolean,false)=false then raise exception 'Confirm the final deal before closing.'; end if;
    if lead.assigned_agent_id is null then raise exception 'Assign an agent first.'; end if;
    event_date:=(payload->>'closingDate')::timestamptz;
    if event_date is null or event_date>now() then raise exception 'Choose a valid non-future closing date.'; end if;
    if coalesce((payload->>'value')::numeric,0)<=0 then raise exception 'Deal value must be greater than zero.'; end if;
    update public.leads set final_property_id=(payload->>'propertyId')::bigint,deal_value=(payload->>'value')::numeric,closing_date=event_date,deal_notes=coalesce(payload->>'notes','') where id=lead.id;
    perform app_private.stage(lead.id,'WON'); perform app_private.close_work(lead.id);
    perform app_private.event(lead.id,'WON','Deal marked as won. Outstanding work cancelled.');
    perform app_private.notify(lead.id,'Deal won: '||lead.customer_name||'.');
  when 'lost' then
    reason:=payload->>'reason';
    if reason is null or reason not in ('Budget Issue','Property Not Suitable','Bought Elsewhere','No Response','Financing Issue','Changed Plans','Other') then raise exception 'Select a lost reason.'; end if;
    if reason='Other' then perform app_private.require_text(payload->>'notes','Lost notes'); end if;
    update public.leads set lost_reason=reason,lost_notes=coalesce(payload->>'notes','') where id=lead.id;
    perform app_private.stage(lead.id,'LOST'); perform app_private.close_work(lead.id);
    perform app_private.event(lead.id,'LOST','Lead marked as lost: '||reason||'. Outstanding work cancelled.');
  else raise exception 'Unknown CRM action.';
  end case;
  return jsonb_build_object('id',lead.id);
end $$;
revoke all on function public.submit_inquiry(jsonb),public.crm_command(text,jsonb) from public,anon,authenticated;
grant execute on function public.submit_inquiry(jsonb) to anon,authenticated;
grant execute on function public.crm_command(text,jsonb) to authenticated;
revoke all on function app_private.require_text(text,text),app_private.event(text,text,text,text),app_private.notify(text,text),app_private.stage(text,text),app_private.sync_follow_up(text),app_private.close_work(text),app_private.create_lead(jsonb,boolean) from public,anon,authenticated;
commit;


-- 202609300003_import_and_public_services.sql
begin;
-- Import preserves IDs. Matching records change only when an admin explicitly enables overwriteExisting.
create function public.import_crm_data(payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
declare row jsonb; n integer:=0; counts jsonb:='{}';
begin
  if not app_private.is_admin() and coalesce(auth.role(),'')<>'service_role' then raise exception 'Administrator access required.' using errcode='42501'; end if;
  if octet_length(payload::text)>10000000 then raise exception 'Import is too large. Split it into smaller batches.'; end if;
  for row in select value from jsonb_array_elements(coalesce(payload->'agents','[]')) loop
    insert into public.agents(id,name,email,phone,avatar,specialization,locations,languages,status) values(row->>'id',row->>'name',row->>'email',row->>'phone',row->>'avatar',row->>'specialization',array(select jsonb_array_elements_text(row->'locations')),array(select jsonb_array_elements_text(row->'languages')),coalesce(row->>'status','ACTIVE')) on conflict(id) do update set name=excluded.name,email=excluded.email,phone=excluded.phone,avatar=excluded.avatar,specialization=excluded.specialization,locations=excluded.locations,languages=excluded.languages,status=excluded.status where coalesce((payload->>'overwriteExisting')::boolean,false);
  end loop;
  for row in select value from jsonb_array_elements(coalesce(payload->'properties','[]')) loop
    insert into public.properties(id,slug,title,category,purpose,location,location_slug,city,price,currency,bedrooms,bathrooms,area,area_unit,featured,off_plan,created_at,tenure,furnished,reference,images,coordinates,description,amenities,agent,status) values((row->>'id')::bigint,row->>'slug',row->>'title',row->>'category',row->>'purpose',row->>'location',row->>'locationSlug',coalesce(row->>'city','Dubai'),(row->>'price')::numeric,coalesce(row->>'currency','AED'),(row->>'bedrooms')::integer,(row->>'bathrooms')::integer,(row->>'area')::numeric,coalesce(row->>'areaUnit','sq ft'),coalesce((row->>'featured')::boolean,false),coalesce((row->>'offPlan')::boolean,false),coalesce((row->>'createdAt')::timestamptz,now()),row->>'tenure',row->>'furnished',row->>'reference',array(select jsonb_array_elements_text(row->'images')),coalesce(row->'coordinates','{}'),row->>'description',array(select jsonb_array_elements_text(row->'amenities')),coalesce(row->'agent','{}'),coalesce(row->>'status','ACTIVE')) on conflict(id) do update set slug=excluded.slug,title=excluded.title,category=excluded.category,purpose=excluded.purpose,location=excluded.location,location_slug=excluded.location_slug,city=excluded.city,price=excluded.price,currency=excluded.currency,bedrooms=excluded.bedrooms,bathrooms=excluded.bathrooms,area=excluded.area,area_unit=excluded.area_unit,featured=excluded.featured,off_plan=excluded.off_plan,created_at=excluded.created_at,tenure=excluded.tenure,furnished=excluded.furnished,reference=excluded.reference,images=excluded.images,coordinates=excluded.coordinates,description=excluded.description,amenities=excluded.amenities,agent=excluded.agent,status=excluded.status where coalesce((payload->>'overwriteExisting')::boolean,false);
  end loop;
  perform setval(pg_get_serial_sequence('public.properties','id'),greatest(1,(select coalesce(max(id),1) from public.properties)),true);
  for row in select value from jsonb_array_elements(coalesce(payload->'leads','[]')) loop
    insert into public.leads(id,customer_name,customer_email,customer_phone,customer_country,property_id,source,purpose,budget_min,budget_max,preferred_location,preferred_contact,status,priority,assigned_agent_id,assigned_at,next_follow_up,created_at,updated_at,final_property_id,deal_value,closing_date,deal_notes,lost_reason,lost_notes) values(row->>'id',row#>>'{customer,name}',row#>>'{customer,email}',row#>>'{customer,phone}',row#>>'{customer,country}',nullif(row->>'propertyId','')::bigint,row->>'source',coalesce(row->>'purpose','buy'),coalesce((row#>>'{budget,min}')::numeric,0),coalesce((row#>>'{budget,max}')::numeric,0),coalesce(row->>'preferredLocation',''),coalesce(row->>'preferredContact','Call'),row->>'status',row->>'priority',row->>'assignedAgentId',(row->>'assignedAt')::timestamptz,(row->>'nextFollowUp')::timestamptz,(row->>'createdAt')::timestamptz,(row->>'updatedAt')::timestamptz,(row#>>'{deal,propertyId}')::bigint,(row#>>'{deal,value}')::numeric,(row#>>'{deal,closingDate}')::timestamptz,row#>>'{deal,notes}',row->>'lostReason',row->>'lostNotes') on conflict(id) do update set customer_name=excluded.customer_name,customer_email=excluded.customer_email,customer_phone=excluded.customer_phone,customer_country=excluded.customer_country,property_id=excluded.property_id,source=excluded.source,purpose=excluded.purpose,budget_min=excluded.budget_min,budget_max=excluded.budget_max,preferred_location=excluded.preferred_location,preferred_contact=excluded.preferred_contact,status=excluded.status,priority=excluded.priority,assigned_agent_id=excluded.assigned_agent_id,assigned_at=excluded.assigned_at,next_follow_up=excluded.next_follow_up,created_at=excluded.created_at,updated_at=excluded.updated_at,final_property_id=excluded.final_property_id,deal_value=excluded.deal_value,closing_date=excluded.closing_date,deal_notes=excluded.deal_notes,lost_reason=excluded.lost_reason,lost_notes=excluded.lost_notes where coalesce((payload->>'overwriteExisting')::boolean,false);
  end loop;
  for row in select value from jsonb_array_elements(coalesce(payload->'tasks','[]')) loop
    insert into public.tasks(id,lead_id,agent_id,title,type,due_date,priority,status,notes,is_follow_up) values(row->>'id',row->>'leadId',row->>'agentId',row->>'title',row->>'type',(row->>'dueDate')::timestamptz,row->>'priority',case when row->>'status'='OVERDUE' then 'PENDING' else row->>'status' end,coalesce(row->>'notes',''),coalesce((row->>'isFollowUp')::boolean,false)) on conflict(id) do update set lead_id=excluded.lead_id,agent_id=excluded.agent_id,title=excluded.title,type=excluded.type,due_date=excluded.due_date,priority=excluded.priority,status=excluded.status,notes=excluded.notes,is_follow_up=excluded.is_follow_up where coalesce((payload->>'overwriteExisting')::boolean,false);
  end loop;
  for row in select value from jsonb_array_elements(coalesce(payload->'viewings','[]')) loop
    insert into public.viewings(id,lead_id,property_id,agent_id,date,meeting_location,notes,status,outcome,outcome_notes,completed_at) values(row->>'id',row->>'leadId',(row->>'propertyId')::bigint,row->>'agentId',(row->>'date')::timestamptz,row->>'meetingLocation',coalesce(row->>'notes',''),row->>'status',row->>'outcome',row->>'outcomeNotes',(row->>'completedAt')::timestamptz) on conflict(id) do update set lead_id=excluded.lead_id,property_id=excluded.property_id,agent_id=excluded.agent_id,date=excluded.date,meeting_location=excluded.meeting_location,notes=excluded.notes,status=excluded.status,outcome=excluded.outcome,outcome_notes=excluded.outcome_notes,completed_at=excluded.completed_at where coalesce((payload->>'overwriteExisting')::boolean,false);
  end loop;
  for row in select value from jsonb_array_elements(coalesce(payload->'activities','[]')) loop
    insert into public.lead_activities(id,lead_id,type,message,author,created_at) values(row->>'id',row->>'leadId',row->>'type',row->>'message',row->>'author',(row->>'createdAt')::timestamptz) on conflict do nothing;
  end loop;
  for row in select value from jsonb_array_elements(coalesce(payload->'notes','[]')) loop
    insert into public.lead_notes(id,lead_id,content,author,created_at) values(row->>'id',row->>'leadId',row->>'content',row->>'author',(row->>'createdAt')::timestamptz) on conflict do nothing;
  end loop;
  for row in select value from jsonb_array_elements(coalesce(payload->'notifications','[]')) loop
    insert into public.notifications(id,lead_id,agent_id,message,created_at) values(row->>'id',row->>'leadId',row->>'agentId',row->>'message',(row->>'createdAt')::timestamptz) on conflict do nothing;
  end loop;
  if payload ? 'settings' then
    insert into public.crm_settings(id,company,email,phone,default_view) values(1,coalesce(payload#>>'{settings,company}','Dubai House'),coalesce(payload#>>'{settings,email}','hello@dubaihouse.demo'),coalesce(payload#>>'{settings,phone}','+971 4 555 0100'),coalesce(payload#>>'{settings,defaultView}','table')) on conflict(id) do update set company=excluded.company,email=excluded.email,phone=excluded.phone,default_view=excluded.default_view where coalesce((payload->>'overwriteExisting')::boolean,false);
  end if;
  for row in select value from jsonb_array_elements(coalesce(payload->'newsletter','[]')) loop
    perform public.subscribe_newsletter(row #>> '{}');
  end loop;
  return jsonb_build_object('leads',(select count(*) from public.leads),'properties',(select count(*) from public.properties),'agents',(select count(*) from public.agents),'tasks',(select count(*) from public.tasks),'viewings',(select count(*) from public.viewings));
end $$;

create function public.visitor_favorites(visitor_token text, property_id bigint default null, initial_ids bigint[] default '{}') returns bigint[] language plpgsql security definer set search_path = '' as $$
declare token_key text; ids bigint[];
begin
  if visitor_token !~ '^[a-f0-9]{64}$' or visitor_token is null then raise exception 'Invalid visitor session.'; end if;
  token_key:=encode(sha256(convert_to(visitor_token,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtext(token_key));
  select favorites into ids from public.visitor_preferences where token_hash=token_key;
  if not found then
    select coalesce(array_agg(distinct p.id),'{}') into ids from public.properties p where p.id=any(initial_ids) and p.status='ACTIVE';
    insert into public.visitor_preferences(token_hash,favorites) values(token_key,ids);
  end if;
  if property_id is not null then
    if not exists(select 1 from public.properties where id=property_id and status='ACTIVE') then raise exception 'Property is unavailable.'; end if;
    if property_id=any(ids) then ids:=array_remove(ids,property_id); else ids:=array_append(ids,property_id); end if;
    if cardinality(ids)>500 then raise exception 'You can save up to 500 properties.'; end if;
    update public.visitor_preferences set favorites=ids,updated_at=now() where token_hash=token_key;
  end if;
  return ids;
end $$;
create function public.subscribe_newsletter(email_address text) returns void language plpgsql security definer set search_path = '' as $$
begin
  if email_address is null or length(email_address)>254 or email_address !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Enter a valid email address.'; end if;
  insert into public.newsletter_subscriptions(email) values(lower(btrim(email_address))) on conflict do nothing;
end $$;

revoke all on function public.import_crm_data(jsonb),public.visitor_favorites(text,bigint,bigint[]),public.subscribe_newsletter(text) from public,anon,authenticated;
grant execute on function public.import_crm_data(jsonb) to authenticated,service_role;
grant execute on function public.visitor_favorites(text,bigint,bigint[]),public.subscribe_newsletter(text) to anon,authenticated;

do $$ declare item text; begin
  if exists(select 1 from pg_publication where pubname='supabase_realtime') then
    foreach item in array array['properties','agents','leads','tasks','viewings','lead_activities','lead_notes','notifications','crm_settings'] loop
      if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=item) then execute format('alter publication supabase_realtime add table public.%I',item); end if;
    end loop;
  end if;
end $$;
notify pgrst,'reload schema';
commit;


-- 202610030001_agent_management.sql
begin;

-- Keep team history after an unused agent is deleted. Only administrators read it.
create table public.agent_events (
  id text primary key default ('AE-' || gen_random_uuid()::text),
  agent_id text not null,
  type text not null check (type in ('CREATED','UPDATED','DELETED')),
  message text not null,
  author text not null,
  actor_id uuid not null,
  created_at timestamptz not null default now()
);
create index agent_events_created on public.agent_events(created_at desc);
alter table public.agent_events enable row level security;
create policy agent_events_read on public.agent_events for select to authenticated
  using ((select app_private.is_admin()));
revoke all on public.agent_events from public, anon, authenticated;
grant select on public.agent_events to authenticated;
grant all on public.agent_events to service_role;
create unique index agents_email_case_insensitive on public.agents(lower(btrim(email)));

-- Deactivation revokes data access even while an existing auth session is valid.
create or replace function app_private.agent_id() returns text
language sql stable security definer set search_path = '' as $$
  select p.agent_id from public.profiles p join public.agents a on a.id=p.agent_id
  where p.id=auth.uid() and p.role='AGENT' and a.status='ACTIVE';
$$;
create or replace function app_private.has_profile() returns boolean
language sql stable security definer set search_path = '' as $$
  select app_private.is_admin() or app_private.agent_id() is not null;
$$;

-- Retain the tested lead workflows behind a private, non-callable implementation.
alter function public.crm_command(text,jsonb) set schema app_private;
alter function app_private.crm_command(text,jsonb) rename to crm_command_base;
revoke all on function app_private.crm_command_base(text,jsonb) from public, anon, authenticated;

create function public.crm_command(command text, payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  actor public.profiles;
  target public.agents;
  agent_key text;
  next_name text;
  next_email text;
  next_phone text;
  next_specialization text;
  next_languages text[];
  next_locations text[];
  next_status text;
  lead_key text;
  batch_count integer := 0;
begin
  select * into actor from public.profiles where id=auth.uid();
  if actor.id is null then raise exception 'Sign in to continue.' using errcode='42501'; end if;
  if actor.role='AGENT' then
    perform 1 from public.agents where id=actor.agent_id and status='ACTIVE' for share;
    if not found then
      raise exception 'Your agent account is inactive. Contact your administrator.' using errcode='42501';
    end if;
  end if;

  if command in ('createAgent','deleteAgent','bulkAssign','assign') and actor.role<>'ADMIN' then
    raise exception 'Administrator access is required.' using errcode='42501';
  end if;

  if command in ('assign','bulkAssign') then
    -- All assignment entry points lock the agent before leads, serializing deactivation.
    select * into target from public.agents where id=payload->>'agentId' for update;
    if target.id is null or target.status<>'ACTIVE' then raise exception 'Select an active agent.'; end if;
    if command='bulkAssign' then
      if jsonb_typeof(payload->'ids') is distinct from 'array' then raise exception 'Select between 1 and 100 leads.'; end if;
      if jsonb_array_length(payload->'ids') not between 1 and 100 then raise exception 'Select between 1 and 100 leads.'; end if;
      for lead_key in select distinct value from jsonb_array_elements_text(payload->'ids') order by value loop
        perform app_private.crm_command_base('assign',jsonb_build_object('id',lead_key,'agentId',target.id));
        batch_count := batch_count+1;
      end loop;
      return jsonb_build_object('count',batch_count);
    end if;
  end if;

  if command in ('createAgent','saveAgent','deleteAgent') then
    if command<>'createAgent' then
      select * into target from public.agents where id=payload->>'id' for update;
      if target.id is null then raise exception 'Agent was not found.'; end if;
      if actor.role<>'ADMIN' and actor.agent_id is distinct from target.id then
        raise exception 'Agent access denied.' using errcode='42501';
      end if;
    end if;
    if command='deleteAgent' then
      if payload->>'confirmName' is distinct from target.name then raise exception 'Type the agent name to confirm deletion.'; end if;
      if exists(select 1 from public.profiles where agent_id=target.id)
        or exists(select 1 from public.leads where assigned_agent_id=target.id)
        or exists(select 1 from public.tasks where agent_id=target.id)
        or exists(select 1 from public.viewings where agent_id=target.id)
        or exists(select 1 from public.notifications where agent_id=target.id) then
        raise exception 'This agent has linked CRM records or a login account. Reassign open work and deactivate the agent instead.';
      end if;
      delete from public.agents where id=target.id;
      insert into public.agent_events(agent_id,type,message,author,actor_id)
        values(target.id,'DELETED','Deleted agent '||target.name||'.',actor.name,actor.id);
      return jsonb_build_object('id',target.id);
    end if;

    next_name := app_private.require_text(payload->>'name','Name');
    next_email := lower(app_private.require_text(coalesce(target.email,payload->>'email'),'Email'));
    next_phone := app_private.require_text(payload->>'phone','Phone');
    next_specialization := app_private.require_text(payload->>'specialization','Specialization');
    if length(next_name)>200 or length(next_specialization)>200 or length(next_email)>254 then raise exception 'Agent profile fields are too long.'; end if;
    if next_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Enter a valid email address.'; end if;
    if next_phone !~ '^[+0-9 ()-]{7,20}$' then raise exception 'Enter a valid phone number.'; end if;
    if length(coalesce(payload->>'languages',''))>1000 or length(coalesce(payload->>'locations',''))>1000 then raise exception 'Languages and locations must be 1000 characters or fewer.'; end if;
    next_languages := array(select distinct btrim(value) from regexp_split_to_table(app_private.require_text(payload->>'languages','Languages'),',') value where btrim(value)<>'');
    next_locations := array(select distinct btrim(value) from regexp_split_to_table(app_private.require_text(coalesce(payload->>'locations',array_to_string(target.locations,',')),'Locations'),',') value where btrim(value)<>'');
    if cardinality(next_languages)=0 or cardinality(next_locations)=0 then raise exception 'Languages and locations are required.'; end if;
    next_status := case when actor.role='ADMIN' then coalesce(payload->>'status',target.status,'ACTIVE') else target.status end;
    if next_status not in ('ACTIVE','INACTIVE') then raise exception 'Choose a valid agent status.'; end if;
    if exists(select 1 from public.agents a where lower(btrim(a.email))=next_email and a.id is distinct from target.id) then raise exception 'An agent with this email already exists.'; end if;
    if next_status='INACTIVE' and (
      exists(select 1 from public.leads where assigned_agent_id=target.id and status not in ('WON','LOST')) or
      exists(select 1 from public.tasks where agent_id=target.id and status not in ('COMPLETED','CANCELLED')) or
      exists(select 1 from public.viewings where agent_id=target.id and status='SCHEDULED')
    ) then raise exception 'Reassign all open leads, tasks and scheduled viewings before deactivating this agent.'; end if;

    agent_key := coalesce(target.id,'agent-'||gen_random_uuid()::text);
    if command='createAgent' then
      insert into public.agents(id,name,email,phone,specialization,languages,locations,status)
        values(agent_key,next_name,next_email,next_phone,next_specialization,next_languages,next_locations,next_status);
    else
      update public.agents set name=next_name,phone=next_phone,specialization=next_specialization,languages=next_languages,locations=next_locations,status=next_status where id=agent_key;
      update public.profiles set name=next_name where agent_id=agent_key;
    end if;
    insert into public.agent_events(agent_id,type,message,author,actor_id)
      values(agent_key,case when command='createAgent' then 'CREATED' else 'UPDATED' end,
        case when command='createAgent' then 'Created' else 'Updated' end||' agent '||next_name||' ('||next_status||').',actor.name,actor.id);
    return jsonb_build_object('id',agent_key);
  end if;

  if command='status' and payload->>'status'='FOLLOW_UP' then
    select a.* into target from public.leads l join public.agents a on a.id=l.assigned_agent_id
      where l.id=coalesce(payload->>'leadId',payload->>'id') for share of a;
    if target.status='INACTIVE' then raise exception 'Reactivate the responsible agent before reopening this lead.'; end if;
  end if;
  return app_private.crm_command_base(command,payload);
end;
$$;
revoke all on function public.crm_command(text,jsonb) from public, anon;
grant execute on function public.crm_command(text,jsonb) to authenticated;

-- Realtime is optional in local SQL tests and enabled only when the publication exists.
do $$ begin
  if exists(select 1 from pg_publication where pubname='supabase_realtime') then
    alter publication supabase_realtime add table public.agent_events;
  end if;
end $$;
commit;


-- 202610030002_property_management.sql
begin;

alter table public.properties add column version bigint not null default 1 check(version > 0);
create index if not exists leads_property_id on public.leads(property_id) where property_id is not null;
create index if not exists leads_final_property_id on public.leads(final_property_id) where final_property_id is not null;
create index if not exists viewings_property_id on public.viewings(property_id);
create function app_private.bump_property_version() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.version := old.version + 1;
  new.updated_at := now();
  return new;
end;
$$;
create trigger properties_version before update on public.properties
  for each row execute function app_private.bump_property_version();

-- Audit entries deliberately retain the property ID after deletion.
create table public.property_events (
  id text primary key default ('PE-' || gen_random_uuid()::text),
  property_id bigint not null,
  type text not null check(type in ('CREATED','UPDATED','ARCHIVED','DELETED')),
  message text not null,
  author text not null,
  actor_id uuid not null,
  created_at timestamptz not null default now()
);
create index property_events_created on public.property_events(created_at desc);
alter table public.property_events enable row level security;
create policy property_events_read on public.property_events for select to authenticated
  using ((select app_private.is_admin()));
revoke all on public.property_events from public, anon, authenticated;
grant select on public.property_events to authenticated;
grant all on public.property_events to service_role;

alter function public.crm_command(text,jsonb) set schema app_private;
alter function app_private.crm_command(text,jsonb) rename to crm_command_team;
revoke all on function app_private.crm_command_team(text,jsonb) from public, anon, authenticated;

create function public.crm_command(command text, payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  actor public.profiles;
  target public.properties;
  result jsonb;
  event_type text;
  event_message text;
  field_name text;
  max_length integer;
  items text[];
begin
  if command not in ('saveProperty','deleteProperty','archiveProperty','setPropertyFeatured') then
    return app_private.crm_command_team(command,payload);
  end if;
  select * into actor from public.profiles where id=auth.uid();
  if actor.id is null or actor.role<>'ADMIN' then
    raise exception 'Administrator access is required.' using errcode='42501';
  end if;
  if octet_length(payload::text)>100000 then raise exception 'Request is too large.'; end if;
  if nullif(payload->>'id','') is not null then
    select * into target from public.properties where id=(payload->>'id')::bigint for update;
    if target.id is null then raise exception 'Property not found.'; end if;
    if coalesce(payload->>'expectedVersion','') <> target.version::text then
      raise exception 'This property has changed since you opened it. Close this dialog, refresh the workspace and review the latest record before trying again.' using errcode='40001';
    end if;
  elsif command<>'saveProperty' then
    raise exception 'Select a property.';
  end if;

  if command='deleteProperty' then
    if (payload->>'confirmTitle') is distinct from target.title then
      raise exception 'Type the property title to confirm deletion.';
    end if;
    -- Row lock plus foreign keys protect against a concurrent new inquiry/viewing.
    if exists(select 1 from public.leads where property_id=target.id or final_property_id=target.id)
      or exists(select 1 from public.viewings where property_id=target.id) then
      raise exception 'This property has linked leads, deals or viewings. Archive it to preserve CRM history.';
    end if;
    delete from public.properties where id=target.id;
    event_type := 'DELETED';
    event_message := 'Deleted property '||target.title||'.';
  elsif command='archiveProperty' then
    update public.properties set status='INACTIVE',featured=false where id=target.id;
    event_type := 'ARCHIVED';
    event_message := 'Archived property '||target.title||'.';
  elsif command='setPropertyFeatured' then
    if jsonb_typeof(payload->'featured') is distinct from 'boolean' then raise exception 'Choose a valid featured value.'; end if;
    update public.properties set featured=(payload->>'featured')::boolean where id=target.id;
    event_type := 'UPDATED';
    event_message := 'Updated featured selection for property '||target.title||'.';
  else
    for field_name,max_length in select * from (values ('title',200),('category',100),('location',200),('locationSlug',200),('description',10000)) limits loop
      if length(btrim(payload->>field_name))>max_length then raise exception '% must be % characters or fewer.',field_name,max_length; end if;
    end loop;
    foreach field_name in array array['images','amenities'] loop
      if jsonb_typeof(payload->field_name)='array' then
        select array_agg(value) into items from jsonb_array_elements_text(payload->field_name);
      else
        items := string_to_array(coalesce(payload->>field_name,''),case when field_name='images' then E'\n' else ',' end);
      end if;
      if cardinality(items)>50 or exists(select 1 from unnest(items) item where length(item)>2000) then
        raise exception '% accepts up to 50 entries of 2000 characters each.',field_name;
      end if;
    end loop;
    foreach field_name in array array['bedrooms','bathrooms'] loop
      if coalesce(payload->>field_name,'') !~ '^\d+$' then raise exception '% must be a non-negative whole number.',field_name; end if;
    end loop;
    event_type := case when target.id is null then 'CREATED' else 'UPDATED' end;
    result := app_private.crm_command_team(command,payload);
    select * into target from public.properties where id=(result->>'id')::bigint;
    event_message := case when event_type='CREATED' then 'Created' else 'Updated' end || ' property '||target.title||' ('||target.status||').';
  end if;
  insert into public.property_events(property_id,type,message,author,actor_id)
    values(target.id,event_type,event_message,actor.name,actor.id);
  return jsonb_build_object('id',target.id);
end;
$$;
revoke all on function public.crm_command(text,jsonb) from public,anon;
grant execute on function public.crm_command(text,jsonb) to authenticated;

do $$ begin
  if exists(select 1 from pg_publication where pubname='supabase_realtime') then
    alter publication supabase_realtime add table public.property_events;
  end if;
end $$;

commit;


