insert into public.public_content(kind,data) values ('locations','[{"slug":"downtown-dubai","name":"Downtown Dubai","tagline":"At the heart of extraordinary.","description":"Landmark architecture, celebrated dining and the rhythm of a global city. Downtown brings the best of Dubai to your doorstep.","image":"https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=2000&q=85","coordinates":{"lat":25.1972,"lng":55.2744}},{"slug":"palm-jumeirah","name":"Palm Jumeirah","tagline":"An island. A world of its own.","description":"Wake to calm water and uninterrupted horizons. Discover private beach living on Dubai’s most distinctive island.","image":"https://images.unsplash.com/photo-1764212193268-dba11709dc38?auto=format&fit=crop&w=1600&q=85","coordinates":{"lat":25.1124,"lng":55.139}},{"slug":"dubai-marina","name":"Dubai Marina","tagline":"Life, beautifully by the water.","description":"A lively waterfront neighbourhood with yacht-lined promenades, independent cafés and exceptional sea-view residences.","image":"https://images.unsplash.com/photo-1682410601760-6372fd33ad2b?auto=format&fit=crop&w=1800&q=85","coordinates":{"lat":25.0805,"lng":55.1403}},{"slug":"emirates-hills","name":"Emirates Hills","tagline":"Space to live exceptionally.","description":"Generous private estates, quiet green streets and golf-course views create a truly peaceful address.","image":"https://images.unsplash.com/photo-1613977257363-707ba9348227?auto=format&fit=crop&w=1200&q=85","coordinates":{"lat":25.0664,"lng":55.1646}},{"slug":"dubai-creek-harbour","name":"Dubai Creek Harbour","tagline":"A fresh perspective on Dubai.","description":"Modern waterfront homes, open promenades and a growing community overlooking the historic Dubai Creek.","image":"https://images.unsplash.com/photo-1682410601760-6372fd33ad2b?auto=format&fit=crop&w=1800&q=85","coordinates":{"lat":25.2068,"lng":55.345}},{"slug":"business-bay","name":"Business Bay","tagline":"Where ambition feels at home.","description":"A connected urban district with canal-side living, contemporary workspaces and the city within easy reach.","image":"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1200&q=85","coordinates":{"lat":25.185,"lng":55.261}},{"slug":"jumeirah","name":"Jumeirah","tagline":"A slower pace by the sea.","description":"Leafy residential streets, boutique destinations and beautiful beaches for an effortlessly balanced lifestyle.","image":"https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=85","coordinates":{"lat":25.204,"lng":55.236}},{"slug":"dubai-hills-estate","name":"Dubai Hills Estate","tagline":"Room to grow, naturally.","description":"Park-side homes, family-friendly amenities and green spaces in a thoughtfully planned neighbourhood.","image":"https://images.unsplash.com/photo-1600047509782-20d39509f26d?auto=format&fit=crop&w=1200&q=85","coordinates":{"lat":25.112,"lng":55.257}}]'::jsonb) on conflict do nothing;
insert into public.public_content(kind,data) values ('categories','[{"slug":"villa","name":"Villas","description":"Refined living spaces","image":"https://images.unsplash.com/photo-1613977257363-707ba9348227?auto=format&fit=crop&w=1200&q=85"},{"slug":"apartment","name":"Apartments","description":"Urban living redefined","image":"https://images.unsplash.com/photo-1682410601760-6372fd33ad2b?auto=format&fit=crop&w=1800&q=85"},{"slug":"townbayt","name":"Townbayts","description":"Space for every story","image":"https://images.unsplash.com/photo-1600047509782-20d39509f26d?auto=format&fit=crop&w=1200&q=85"},{"slug":"pentbayt","name":"Pentbayts","description":"Elevated experiences","image":"https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=85"},{"slug":"commercial","name":"Commercial","description":"Spaces for growth","image":"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1200&q=85"}]'::jsonb) on conflict do nothing;
insert into public.public_content(kind,data) values ('articles','[{"slug":"finding-your-dubai-neighbourhood","title":"Finding your place in Dubai","category":"Neighbourhoods","date":"2026-09-15","image":"https://images.unsplash.com/photo-1682410601760-6372fd33ad2b?auto=format&fit=crop&w=1800&q=85","excerpt":"From the waterfront to the heart of the city, discover the neighbourhood that fits your everyday.","paragraphs":["A home is more than its floor plan. It is the morning walk, the familiar café and the journey back at the end of the day. Choosing a neighbourhood begins with understanding how you want to spend your time.","Downtown offers a connected city lifestyle, while Dubai Marina brings long waterfront walks and lively evenings. Palm Jumeirah offers a more secluded setting with wide sea views. Each has its own rhythm.","Visit at different times of day, try your regular commute and explore local amenities on foot. Practical details often reveal more than a photograph. Our advisors can help you build a shortlist around your priorities."]},{"slug":"a-considered-property-investment","title":"A considered approach to property investment","category":"Investment","date":"2026-09-08","image":"https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=2000&q=85","excerpt":"The questions to ask before choosing a property, from your time horizon to ongoing costs.","paragraphs":["Start with your objectives. A home for future use and a rental property may call for very different decisions. Define your time horizon, budget and tolerance for uncertainty before comparing individual listings.","Look beyond the advertised purchase price. Ongoing service charges, maintenance, financing and transaction costs all affect affordability. Rental demand and returns vary, and past performance does not guarantee future results.","Request current documentation and independent professional advice before making any commitment. The information in this demo is general editorial content, not financial or legal advice."]},{"slug":"the-art-of-waterfront-living","title":"The art of waterfront living","category":"Lifestyle","date":"2026-08-28","image":"https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=85","excerpt":"Open horizons, natural light and space to slow down. A different perspective on home.","paragraphs":["There is a quiet appeal to a home by the water. Shifting light and open views bring a sense of space to everyday routines, from a morning coffee to an evening with friends.","When viewing waterfront homes, consider orientation, outdoor space and how the rooms connect. Ask about building maintenance and explore the surrounding promenade to understand the atmosphere.","The best home is the one that works for your life. Think about the spaces you will use every day, the people you will welcome and the details that make you feel at ease."]},{"slug":"a-guide-to-viewing-your-next-home","title":"A fresh perspective on your next viewing","category":"Buying guides","date":"2026-08-17","image":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=85","excerpt":"A thoughtful checklist to help you make the most of every property viewing.","paragraphs":["Begin with a short list of essentials and a separate list of preferences. This helps you stay focused when a beautiful view or a striking interior catches your attention.","Look at storage, daylight, noise and the practical flow of rooms. Take notes during each viewing so you can compare properties clearly later. Always request permission before taking photographs.","Ask questions about building management, maintenance history and shared facilities. Take the time you need, and arrange a second visit for any home you are seriously considering."]}]'::jsonb) on conflict do nothing;
insert into public.public_content(kind,data) values ('testimonials','[{"id":1,"quote":"Dubai bayt made our investment journey seamless. Their team was professional, transparent, and truly understood our goals. We couldn’t be happier with our new apartment in Downtown Dubai.","name":"James Carter","role":"Investor from the UK","rating":5,"avatar":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=100&q=85"},{"id":2,"quote":"From our first conversation to finding the right neighbourhood, the advice was thoughtful and personal. We found a place that feels like home from the moment you walk in.","name":"Amelia Ross","role":"Homeowner from Australia","rating":5,"avatar":"https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=100&q=85"},{"id":3,"quote":"We appreciated the clear explanations and attention to the small details. The team helped us explore our options with confidence and at our own pace.","name":"Arjun Mehta","role":"Investor from India","rating":5,"avatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=100&q=85"}]'::jsonb) on conflict do nothing;
